-- PRJ-02 Projects: any project (aircraft addition, NP change, new base, Part-IS…) = phases + tasks, created blank or from a template,
-- orchestrating objects that already exist in S.A.M. (manual revisions, authority files, certificates) instead of duplicating them.

create table if not exists project_templates (
  code text primary key,
  name text not null,
  description text,
  entities entity_code[] not null default '{}',
  phases jsonb not null default '[]',      -- [{"key":"acq","label":"Aircraft acquisition"}]
  tasks jsonb not null default '[]',       -- [{"key","phase","title","owner_role","days","deps":[keys],"link_kind","link_ref","detail","source"}]
  pivots text[] not null default '{}',     -- which pivot fields the project asks for: aircraft_type, aircraft_reg, np_post_code
  active boolean not null default true,
  ord int not null default 0
);

create table if not exists projects (
  id uuid primary key default gen_random_uuid(),
  entity entity_code not null references entities(code),
  template_code text references project_templates(code),
  title text not null,
  description text,
  owner_role text,
  owner_person uuid references people(id),
  status text not null default 'open' check (status in ('open','on_hold','closed')),
  pivot jsonb not null default '{}',       -- {"aircraft_type":"GL7T","aircraft_reg":"9H-MAX","np_post_code":"NPFO"}
  started_at date not null default current_date,
  target_date date,
  closed_at date,
  lessons text,
  created_by uuid references people(id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists projects_entity_status on projects (entity, status);

create table if not exists project_phases (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  ord int not null default 0,
  key text,
  label text not null
);
create index if not exists project_phases_project on project_phases (project_id, ord);

create table if not exists project_tasks (
  id uuid primary key default gen_random_uuid(),
  project_id uuid not null references projects(id) on delete cascade,
  phase_id uuid references project_phases(id) on delete set null,
  ord int not null default 0,
  key text,
  title text not null,
  detail text,
  source text,
  owner_role text,
  owner_person uuid references people(id),
  status text not null default 'todo' check (status in ('todo','in_progress','waiting','blocked','done','not_needed')),
  not_needed_reason text,
  days int,                                -- expected duration, for the projected dates
  due date,                                -- set by hand; otherwise projected from dependencies
  started_at date,
  done_at date,
  done_by uuid references people(id),
  link_kind text check (link_kind in ('manual','authority_file','certificate','moc')),
  link_ref text,                           -- manual code (OM-A), authority file type (AC-NEW), certificate kind (insurance)
  link_id uuid,                            -- the real object once it exists: revision id, authority file id, certificate id
  note text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists project_tasks_project on project_tasks (project_id, ord);
create index if not exists project_tasks_link on project_tasks (link_kind, link_id);

create table if not exists project_task_deps (
  task_id uuid not null references project_tasks(id) on delete cascade,
  depends_on uuid not null references project_tasks(id) on delete cascade,
  primary key (task_id, depends_on)
);

alter table authority_files add column if not exists project_id uuid references projects(id) on delete set null;
create index if not exists authority_files_project on authority_files (project_id);

-- RLS: read within the entity scope; writes go through the server (service role) after the app's own checks
alter table project_templates enable row level security;
alter table projects enable row level security;
alter table project_phases enable row level security;
alter table project_tasks enable row level security;
alter table project_task_deps enable row level security;
drop policy if exists pt_read on project_templates; create policy pt_read on project_templates for select to authenticated using (true);
drop policy if exists pr_scope on projects; create policy pr_scope on projects for select to authenticated using (entity = any(my_entities()));
drop policy if exists pph_scope on project_phases; create policy pph_scope on project_phases for select to authenticated using (exists (select 1 from projects p where p.id = project_id and p.entity = any(my_entities())));
drop policy if exists ptk_scope on project_tasks; create policy ptk_scope on project_tasks for select to authenticated using (exists (select 1 from projects p where p.id = project_id and p.entity = any(my_entities())));
drop policy if exists ptd_scope on project_task_deps; create policy ptd_scope on project_task_deps for select to authenticated using (exists (select 1 from project_tasks t join projects p on p.id = t.project_id where t.id = task_id and p.entity = any(my_entities())));

-- Linked objects close their task by themselves: a manual revision published, an authority file approved / published / closed.
create or replace function project_task_follow_revision() returns trigger language plpgsql as $$
begin
  if new.step in ('published','repository') and (old.step is distinct from new.step) then
    update project_tasks set status = 'done', done_at = current_date, updated_at = now()
      where link_kind = 'manual' and link_id = new.id and status not in ('done','not_needed');
  end if;
  return new;
end $$;
drop trigger if exists project_task_follow_revision_trg on revisions;
create trigger project_task_follow_revision_trg after update of step on revisions for each row execute function project_task_follow_revision();

create or replace function project_task_follow_file() returns trigger language plpgsql as $$
begin
  if new.stage in ('approved','published','closed') and (old.stage is distinct from new.stage) then
    update project_tasks set status = 'done', done_at = current_date, updated_at = now()
      where link_kind = 'authority_file' and link_id = new.id and status not in ('done','not_needed');
  elsif new.stage in ('submitted','remarks') and (old.stage is distinct from new.stage) then
    update project_tasks set status = 'waiting', updated_at = now()
      where link_kind = 'authority_file' and link_id = new.id and status in ('todo','in_progress');
  end if;
  return new;
end $$;
drop trigger if exists project_task_follow_file_trg on authority_files;
create trigger project_task_follow_file_trg after update of stage on authority_files for each row execute function project_task_follow_file();

